def roman_to_integer(numeral):
  romans = {"I": 1,
            "V": 5,
            "X": 10,
            "L": 50,
            "C": 100,
            "D": 500,
            "M": 1000
            }
  num = 0
  i = 0
  while i < len(numeral):
    if i+1 < len(numeral):
      if romans[numeral[i]] >= romans[numeral[i+1]]:
        num = num + romans[numeral[i]]
      else :
        num = num + romans[numeral[i+1]] - romans[numeral[i]]
        i+=1
    else:
      num = num + romans[numeral[i]]
    i+=1
  return num

def max_sum_k_elements(array, k):
    max_sum = array[0]
    for i in range(len(array)-k+1):
        sum_temp = 0
        for j in range(k):
            sum_temp += array[i+j]
        if sum_temp > max_sum:
            max_sum = sum_temp
